def maximumANDSum(nums: list[int], numSlots: int) -> int:
    memo = {}
    n = len(nums)
    def dp(i, mask):
        if i == n: return 0
        state = (i, mask)
        if state in memo: return memo[state]
        ans = 0
        for slot in range(1, numSlots + 1):
            slot_base = 3 ** (slot - 1)
            slot_count = (mask // slot_base) % 3
            if slot_count < 2:
                val = (nums[i] & slot) + dp(i + 1, mask + slot_base)
                if val > ans: ans = val
        memo[state] = ans
        return ans
    return dp(0, 0)

